package marketplace

// Request-understanding corpus (Phase 4C hardening). Every synthetic buyer
// message is read the way production reads it, in the same order:
//
//	workflow.FirstReading (small talk / reference with nothing shown)
//	-> ParseSelectionReply (offer selection replies never become requests)
//	-> the real heuristic extractor's output (generated by
//	   scripts/eval/build_request_corpus.py, not hand-written)
//	-> workflow.Assess (the deterministic policy)
//
// The corpus is synthetic and hand-written: these are measurements of the
// policy on a fixture, not production evidence. Set CORPUS_REPORT=path to
// write the measurements as JSON.

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/middleman/backend/infrastructure/ai"
	"github.com/middleman/backend/internal/autonomy"
	"github.com/middleman/backend/internal/request"
	"github.com/middleman/backend/internal/workflow"
)

type corpusCase struct {
	ID            string            `json:"id"`
	Tags          []string          `json:"tags"`
	Text          string            `json:"text"`
	KnownLocation string            `json:"known_location"`
	Expect        string            `json:"expect"`
	Field         string            `json:"field"`
	KnownGap      string            `json:"known_gap"`
	Extraction    map[string]any    `json:"extraction"`
	Request       map[string]string `json:"request"`
	ExpectField   string            `json:"expect_field"`
}

type corpus struct {
	FirstMessages []corpusCase `json:"first_messages"`
	Answers       []corpusCase `json:"answers"`
}

func loadCorpus(t *testing.T) corpus {
	t.Helper()
	b, err := os.ReadFile("testdata/request_corpus.json")
	if err != nil {
		t.Fatalf("corpus: %v (run scripts/eval/build_request_corpus.py)", err)
	}
	var c corpus
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	return c
}

func extractionOf(t *testing.T, c corpusCase) *ai.ExtractionResult {
	t.Helper()
	if c.Extraction == nil {
		t.Fatalf("%s: no extraction in the fixture (run scripts/eval/build_request_corpus.py)", c.ID)
	}
	b, _ := json.Marshal(c.Extraction)
	var ex ai.ExtractionResult
	if err := json.Unmarshal(b, &ex); err != nil {
		t.Fatal(err)
	}
	return &ex
}

// readFirstMessage returns the outcome and the field Majo would ask about.
func readFirstMessage(t *testing.T, c corpusCase) (string, string) {
	if r := workflow.FirstReading(c.Text, 0); r != "" {
		return r, ""
	}
	if ParseSelectionReply(c.Text).Kind != ReplyNone {
		return "selection_reply", ""
	}
	ex := extractionOf(t, c)
	req := &request.BuyerRequest{RawMessage: c.Text, Category: ex.Category, Product: ex.Product, Variant: ex.Variant,
		BudgetMin: ex.BudgetMin, BudgetMax: ex.BudgetMax, Location: ex.Location, Condition: ex.Condition, Quantity: ex.Quantity,
		Confidence: ex.Confidence, ExtractedData: c.Extraction}
	a := workflow.Assess(req, c.KnownLocation, workflow.History{Asked: map[string]int{}, Skipped: map[string]bool{}}, autonomy.DefaultParams())
	return a.Outcome, a.Missing
}

type corpusMetrics struct {
	Note                   string         `json:"note"`
	Messages               int            `json:"messages"`
	Correct                int            `json:"correct"`
	KnownGaps              int            `json:"known_gaps"`
	FalseConfirmations     int            `json:"false_confirmations"`       // should not proceed, but Majo would confirm and route
	UnnecessaryQuestions   int            `json:"unnecessary_clarification"` // clear, but Majo would ask
	UnresolvedAmbiguity    int            `json:"unresolved_ambiguity"`      // ambiguous / conflicting read as clear
	JunkRequests           int            `json:"junk_requests"`             // small talk / selection / reference that would create a request
	PolicyMisses           int            `json:"policy_misses"`
	PolicyFalsePositives   int            `json:"policy_false_positives"`
	WrongQuestion          int            `json:"wrong_question"`
	ByExpected             map[string]int `json:"by_expected"`
	ByOutcome              map[string]int `json:"by_outcome"`
	Answers                int            `json:"answers"`
	AnswersCorrect         int            `json:"answers_correct"`
	AnswerFalseMerges      int            `json:"answer_false_merges"` // a long sentence stored as a field value
	Mismatches             []string       `json:"mismatches"`
	KnownGapDetails        []string       `json:"known_gap_details"`
	DuplicateRequestsByAns int            `json:"duplicate_requests_by_answers"`
}

func isQuestion(o string) bool {
	return o == workflow.OutcomeMissing || o == workflow.OutcomeAmbiguous || o == workflow.OutcomeConflicting
}

func TestRequestUnderstandingCorpus(t *testing.T) {
	c := loadCorpus(t)
	m := corpusMetrics{Note: "synthetic hand-written corpus; heuristic extractor; not production evidence",
		ByExpected: map[string]int{}, ByOutcome: map[string]int{}}
	noRequest := map[string]bool{"small_talk": true, "selection_reply": true, "reference_without_context": true}
	for _, cs := range c.FirstMessages {
		got, field := readFirstMessage(t, cs)
		m.Messages++
		m.ByExpected[cs.Expect]++
		m.ByOutcome[got]++
		ok := got == cs.Expect && (cs.Field == "" || cs.Field == field)
		switch {
		case got == workflow.OutcomeClear && cs.Expect != workflow.OutcomeClear:
			m.FalseConfirmations++
			if cs.Expect == workflow.OutcomeAmbiguous || cs.Expect == workflow.OutcomeConflicting {
				m.UnresolvedAmbiguity++
			}
		case cs.Expect == workflow.OutcomeClear && isQuestion(got):
			m.UnnecessaryQuestions++
		case noRequest[cs.Expect] && !noRequest[got]:
			m.JunkRequests++
		case got == cs.Expect && cs.Field != "" && cs.Field != field:
			m.WrongQuestion++
		}
		if cs.Expect == workflow.OutcomePolicy && got != workflow.OutcomePolicy {
			m.PolicyMisses++
		}
		if got == workflow.OutcomePolicy && cs.Expect != workflow.OutcomePolicy {
			m.PolicyFalsePositives++
		}
		line := fmt.Sprintf("%s %q: expected %s/%s, got %s/%s", cs.ID, cs.Text, cs.Expect, cs.Field, got, field)
		switch {
		case ok:
			m.Correct++
		case cs.KnownGap != "":
			m.KnownGaps++
			m.KnownGapDetails = append(m.KnownGapDetails, line+" — "+cs.KnownGap)
		default:
			m.Mismatches = append(m.Mismatches, line)
		}
	}
	for _, cs := range c.Answers {
		m.Answers++
		ex := extractionOf(t, cs)
		req := &request.BuyerRequest{Product: strPtr(cs.Request["product"])}
		patch, got := workflow.AnswerPatch(cs.Field, cs.Text, ex, req)
		val := patchValue(patch, cs.ExpectField)
		if cs.ExpectField == "none" {
			if !got {
				m.AnswersCorrect++
			} else {
				m.AnswerFalseMerges++
				m.Mismatches = append(m.Mismatches, fmt.Sprintf("%s %q: a sentence was stored as %s", cs.ID, cs.Text, cs.Field))
			}
			continue
		}
		if got && strings.EqualFold(val, cs.Expect) {
			m.AnswersCorrect++
		} else {
			m.Mismatches = append(m.Mismatches, fmt.Sprintf("%s %q (%s): expected %s=%q, got %q (understood=%v)", cs.ID, cs.Text, cs.Field, cs.ExpectField, cs.Expect, val, got))
		}
	}
	sort.Strings(m.Mismatches)
	if p := os.Getenv("CORPUS_REPORT"); p != "" {
		b, _ := json.MarshalIndent(m, "", " ")
		_ = os.WriteFile(p, b, 0o644)
	}
	t.Logf("corpus: %d messages, %d correct, %d known gaps; false confirmations %d, unnecessary questions %d, junk requests %d, policy misses %d / false positives %d; answers %d/%d",
		m.Messages, m.Correct, m.KnownGaps, m.FalseConfirmations, m.UnnecessaryQuestions, m.JunkRequests, m.PolicyMisses, m.PolicyFalsePositives, m.AnswersCorrect, m.Answers)
	for _, g := range m.KnownGapDetails {
		t.Logf("known gap: %s", g)
	}
	// Safety properties hold on every case, known gaps included.
	if m.FalseConfirmations != 0 || m.JunkRequests != 0 || m.PolicyMisses != 0 || m.PolicyFalsePositives != 0 || m.AnswerFalseMerges != 0 {
		t.Errorf("safety: false confirmations %d, junk requests %d, policy misses %d, policy false positives %d, false merges %d",
			m.FalseConfirmations, m.JunkRequests, m.PolicyMisses, m.PolicyFalsePositives, m.AnswerFalseMerges)
	}
	for _, mm := range m.Mismatches {
		t.Errorf("mismatch: %s", mm)
	}
}

func strPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func patchValue(p request.Fields, field string) string {
	d := func(s *string) string {
		if s == nil {
			return ""
		}
		return *s
	}
	switch field {
	case "variant":
		return d(p.Variant)
	case "location":
		return d(p.Location)
	case "condition":
		return d(p.Condition)
	case "product":
		return d(p.Product)
	case "budget_max":
		if p.BudgetMax != nil {
			return fmt.Sprint(*p.BudgetMax)
		}
	}
	return ""
}
